    code: { title: 'Bayes by counting (Python)', language: 'python', code: 'def posterior(prevalence, sensitivity, specificity):\n    sick = 10_000 * prevalence\n    true_pos = sick * sensitivity\n    false_pos = (10_000 - sick) * (1 - specificity)\n    return true_pos / (true_pos + false_pos)\n# posterior(0.01, 0.99, 0.99) -> 0.5\n# posterior(0.30, 0.99, 0.99) -> 0.977  (high prevalence recovers accuracy)', explanation: 'Concrete counts beat symbolic Bayes every time in the exam hall — and in production ML.' },
    diagram: { title: 'From prevalence to posterior', caption: 'Positive predictive value collapses at low prevalence.', mermaid: 'flowchart LR\n  A[Population Ω] --> B["Sick (prevalence p)"]\n  A --> C["Healthy (1−p)"]\n  B --> D["True positive rate (sensitivity)"]\n  C --> E["False positive rate (1−specificity)"]\n  D --> F["P(sick | positive)"]\n  E --> F' },
